mapper.select:
SELECT f.id as flierId, f.title, f.description, f.cta_link as ctaLink, f.content_link as contentLink, f.likes, f.copies, f.cta_clicks as ctaClicks, f.status, f.created_at as createdAt, f.modified_at as modifiedAt FROM flier f WHERE f.author_brand_id = #{authorBrandId}
AND (locate(#{dto.q}, f.title)>0)
AND f.status = #{dto.status}
ORDER BY f.created_at DESC

SELECT fc.id as flierCopyId, f.id as flierId, f.title, f.description, f.cta_link as ctaLink, f.content_link as contentLink, f.likes, f.copies, f.cta_clicks as ctaClicks, fc.has_like as hasLike, fc.has_click_cta as hasClickCta, b.id as authorBrandId, b.avator as authorAvatar, b.brand_name as authorName, b.customer_id as authorUserId FROM flier_copy fc INNER JOIN flier f ON fc.flier_id = f.id INNER JOIN brand b ON f.author_brand_id = b.id WHERE fc.receiver_brand_id = #{receiverBrandId}
AND (locate(#{dto.q}, f.title)>0)
ORDER BY fc.created_at DESC
